+    private ComboBox<String> fractionCombo(String name) {
+        ComboBox<String> c = new ComboBox<>();
+        FX.name(c, name);
+        c.setEditable(true);
+        c.getItems().setAll(
+            "0.0",
+            "0.5",
+            "1.0",
+            "MAX",
+            "MIN",
+            "+Infinity",
+            "-Infinity",
+            "NaN"
+        );
+        c.getSelectionModel().select(0);
+        c.setPrefWidth(80);
+        return c;
+    }
+
+    private static double parseFraction(ComboBox<String> c) {
+        String v = c.getValue();
+        if (v != null) {
+            try {
+                switch(v) {
+                case "MAX":
+                    return Double.MAX_VALUE;
+                case "MIN":
+                    return -Double.MAX_VALUE;
+                case "+Infinity":
+                    return Double.POSITIVE_INFINITY;
+                case "-Infinity":
+                    return Double.NEGATIVE_INFINITY;
+                case "NaN":
+                    return Double.NaN;
+                }
+                return Double.parseDouble(v);
+            } catch (Exception e) {
+                // ignore
+            }
+        }
+        return Double.NaN;
+    }
+
+    private void scrollTo() {
+        double x = parseFraction(horFraction);
+        double y = parseFraction(verFraction);
+        control.scrollCaretInView(x, y);
+    }

